# v1.20.0 (lot E) : démonstration — accueils (bourse, services civiques, stagiaires), bénévole qui saisit des inscriptions, intervenante, mobile, aucune donnée de santé
from playwright.sync_api import sync_playwright
import re
errs=[]; fails=[]
def check(c,msg):
    print(('ok - ' if c else 'ECHEC - ')+msg)
    if not c: fails.append(msg)
SANTE=re.compile(r'hospital|maladie|décès|deces|EHPAD|médic|diagnostic|traitement|allerg|handicap|difficultés rencontrées|naissance',re.I)
with sync_playwright() as p:
    b=p.chromium.launch(executable_path='/usr/bin/google-chrome',args=['--no-sandbox'])
    ctx=b.new_context(viewport={'width':1280,'height':900}); pg=ctx.new_page()
    pg.on('console',lambda m: errs.append(m.text) if m.type=='error' and 'fonts.g' not in m.text and 'ERR_' not in m.text else None)
    pg.on('pageerror',lambda e: errs.append(str(e)))
    pg.goto('http://localhost:8765/index.html'); pg.evaluate("localStorage.clear()"); pg.reload(); pg.wait_for_selector('text=Essayer comme administratrice'); pg.click('text=Essayer comme administratrice'); pg.wait_for_selector('nav.side'); pg.wait_for_timeout(900)
    t=pg.inner_text('.alertes')
    check('convention à signer' in t and 'bilan' in t and 'Bourse : 1 jeune en retard' in t,'accueil : alertes des accueils (convention, bilan, retard des heures) : '+t[:300].replace('\n',' | '))
    pg.click('.alertes button:has-text("à signer"):has-text("Exemple")'); pg.wait_for_selector('[data-action=ac-tab]'); pg.wait_for_timeout(500)
    check(pg.locator('.cand').count()==1 and 'Exemple' in pg.inner_text('main'),'l\'alerte ouvre l\'onglet des services civiques')
    pg.click('[data-action=ac-tab][data-v=bourse]'); pg.wait_for_timeout(300)
    t=pg.inner_text('main'); check('Fictif' in t and '5,5' in t and '/ 50' in t and 'En retard' in t,'bourse : heures validées 5,5 / 50 et retard signalé')
    pg.click('.cand >> nth=0'); pg.wait_for_selector('[data-action=ac-h-add]'); m=pg.inner_text('.modal')
    check('Atelier créatif' in m and 'Saisi par' in m and 'attendues à ce jour' in m,'fiche : journal d\'heures, « saisi par », heures attendues')
    pg.click('[data-action=ac-dossier][data-v=valide]'); pg.wait_for_selector('#v1'); pg.click('#saveV'); pg.wait_for_timeout(500)
    check('validé le' in pg.inner_text('.modal'),'validation du dossier notée')
    pg.click('[data-action=ac-dossier][data-v=verse]'); pg.wait_for_selector('#v2'); pg.click('#saveV'); pg.wait_for_timeout(500)
    check('bourse de 500 € versée le' in pg.inner_text('.modal'),'versement de la bourse noté (500 € par défaut)')
    pg.click('.modal [data-action=close]'); pg.click('[data-action=ac-tab][data-v=civique]'); pg.wait_for_timeout(300)
    pg.click('[data-action=ac-form][data-type=civique]'); pg.wait_for_selector('#a14'); m=pg.inner_text('.modal')
    check('Points d\'organisation à revoir' in m and '✔ À écrire' in m and '✘ À ne pas écrire' in m and 'difficultés' not in m.lower(),'service civique : « points d\'organisation à revoir » et avertissement ✔/✘')
    check(pg.locator('input[type=date]').count()==3 and 'naissance' not in m.lower(),'aucune date de naissance (jeunes possiblement mineurs)')
    pg.click('.modal [data-action=close]'); pg.click('[data-action=ac-tab][data-v=stagiaire]'); pg.wait_for_timeout(300)
    check('Modèle' in pg.inner_text('main') and 'Signée' in pg.inner_text('main'),'stagiaires : fiche et convention signée')
    pg.click('.cand >> nth=0'); pg.wait_for_selector('[data-action=ac-r-add]'); pg.fill('#r1','2026-12-01'); pg.fill('#r2','Point de fin de stage'); pg.click('[data-action=ac-r-add]'); pg.wait_for_timeout(500)
    check('Point de fin de stage' in pg.inner_text('.modal'),'rendez-vous de suivi ajouté')
    check(not SANTE.search(pg.inner_text('.modal')),'aucun terme de santé dans la fiche')
    pg.click('.modal [data-action=close]')
    pg.click('[data-action=ac-tab][data-v=chiffres]'); pg.wait_for_selector('#ac-an'); t=pg.inner_text('main')
    check('Bourses versées dans l\'année' in t and 'Bénévoles actifs' in t and pg.locator('[data-action=ac-xlsx]').count()==1 and pg.locator('[data-action=ac-pdf]').count()==1,'chiffres : tableau et exports Excel/PDF')
    # Paramètres
    pg.click('nav.side [data-v=parametres]'); pg.wait_for_selector('#p-aed'); m=pg.inner_text('main')
    check('Accueils (jeunes adultes' in m and pg.input_value('#p-aoh')=='50' and pg.input_value('#p-amb')=='500' and '✘ À ne pas écrire' in m,'Paramètres : objectif 50 h, bourse 500 €, avertissement')
    pg.uncheck('#p-m-accueils'); pg.click('[data-action=param-save]'); pg.wait_for_timeout(600)
    check(pg.locator('nav.side [data-v=accueils]').count()==0,'module Accueils désactivable : menu masqué')
    pg.check('#p-m-accueils'); pg.click('[data-action=param-save]'); pg.wait_for_timeout(600)
    check(pg.locator('nav.side [data-v=accueils]').count()==1,'module réactivé')
    # Équipe
    pg.click('nav.side [data-v=equipe]'); pg.wait_for_selector('[data-action=equipe-form]'); pg.wait_for_timeout(400)
    pg.click('[data-action=equipe-form] >> nth=0'); pg.wait_for_selector('#blocAcces'); check('Accès provisoires' in pg.inner_text('.modal'),'Équipe : bloc « Accès provisoires »')
    pg.click('.modal [data-action=close]')
    # intervenante démo
    pg.click('[data-action=compte]'); pg.click('.modal [data-action=logout]'); pg.wait_for_selector('text=Essayer comme intervenante'); pg.click('text=Essayer comme intervenante'); pg.wait_for_selector('text=Mes activités')
    check(pg.locator('nav.side [data-v=inscrire]').count()==0 and pg.locator('nav.side [data-v=accueils]').count()==0,'intervenante : ni Inscriptions ni Accueils')
    # bénévole démo
    pg.click('[data-action=compte]'); pg.click('.modal [data-action=logout]'); pg.wait_for_selector('text=Essayer comme bénévole'); pg.click('text=Essayer comme bénévole'); pg.wait_for_selector('nav.side'); pg.wait_for_timeout(400)
    check(pg.locator('nav.side [data-v=inscrire]').count()==1 and pg.locator('nav.side [data-v=accueils]').count()==0 and pg.locator('nav.side [data-v=seniors]').count()==0,'bénévole : Inscriptions oui ; Accueils et Personnes non')
    pg.click('nav.side [data-v=inscrire]'); pg.wait_for_selector('#ins-act'); opts=pg.evaluate("[...document.querySelectorAll('#ins-act option')].map(o=>o.value).filter(Boolean)")
    pg.select_option('#ins-act',opts[0]); pg.wait_for_selector('#ins-q'); pg.fill('#ins-q','Pe'); pg.wait_for_timeout(400)
    t=pg.inner_text('#ins-liste'); check('Petit' in t and 'Inscrire' in t or 'Déjà' in t,'recherche dans la liste restreinte (démonstration)')
    check(not re.search(r'0[1-9]( ?\d\d){4}|rue |/19\d\d',t),'aucun téléphone, adresse ni date de naissance')
    # mobile
    pg.set_viewport_size({'width':390,'height':800}); pg.wait_for_timeout(300)
    check(pg.evaluate("document.documentElement.scrollWidth<=window.innerWidth+2"),'mobile : pas de défilement horizontal (Inscriptions)')
    pg.click('[data-action=compte]'); pg.click('.modal [data-action=logout]'); pg.wait_for_selector('text=Essayer comme administratrice'); pg.click('text=Essayer comme administratrice'); pg.wait_for_selector('nav.side'); pg.wait_for_timeout(400)
    pg.click('nav.side [data-v=accueils]'); pg.wait_for_selector('[data-action=ac-tab]'); pg.click('[data-action=ac-tab][data-v=bourse]'); pg.wait_for_timeout(300); pg.click('.cand >> nth=0'); pg.wait_for_selector('.modal')
    check(pg.evaluate("document.documentElement.scrollWidth<=window.innerWidth+2"),'mobile : pas de défilement horizontal (fiche d\'accueil)')
    check(len(errs)==0,'aucune erreur console : '+str(errs[:3]))
    print('erreurs',errs); print('ÉCHECS :',fails or 'aucun')
